import pandas as pd

def run(inputs: dict) -> dict:
    df = inputs["payments"].copy()

    valid_currencies = {"USD", "EUR", "GBP"}

    def classify(row):
        amount = row["amount"]
        currency = row["currency"]
        country = row["country"]

        if pd.isna(amount):
            return "AMT_NULL"
        if amount <= 0:
            return "AMT_NONPOS"
        if pd.isna(currency) or currency not in valid_currencies:
            return "CCY_INVALID"
        if pd.isna(country):
            return "CTRY_NULL"
        return None

    reason_codes = df.apply(classify, axis=1)

    is_rejected = reason_codes.notna()

    clean_df = df.loc[~is_rejected].copy()
    clean_df["amount"] = clean_df["amount"].round(2)

    rejects_df = df.loc[is_rejected].copy()
    rejects_df["reason_code"] = reason_codes.loc[is_rejected]

    clean_df = clean_df.reset_index(drop=True)
    rejects_df = rejects_df.reset_index(drop=True)

    return {
        "payments_clean": clean_df,
        "payments_rejects": rejects_df,
    }
